package pe.vichaval.gestionriego.tesoreria.entity;import jakarta.persistence.*;import java.math.*;import java.time.*;import pe.vichaval.gestionriego.agricultor.entity.Agricultor;import pe.vichaval.gestionriego.tesoreria.dto.PagoForm;@Entity@Table(name="pagos")public class Pago{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private BigDecimal monto;@Column(nullable=false)private LocalDate fecha;@Column(nullable=false)private String concepto;@Column(nullable=false,unique=true)private String comprobante;@Column(nullable=false)private String metodo;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="agricultor_id")private Agricultor agricultor;protected Pago(){}public Pago(PagoForm f,Agricultor a){monto=f.getMonto();fecha=f.getFecha();concepto=f.getConcepto();comprobante=f.getComprobante();metodo=f.getMetodo();agricultor=a;}public BigDecimal getMonto(){return monto;}public LocalDate getFecha(){return fecha;}public String getConcepto(){return concepto;}public String getComprobante(){return comprobante;}public String getMetodo(){return metodo;}public Agricultor getAgricultor(){return agricultor;}}